   309	static inline int read_and_check_crc(spng_ctx *ctx)
   310	{
   311	    if(ctx == NULL) return 1;
   312	
   313	    int ret;
   314	    ret = read_data(ctx, 4);
   315	    if(ret) return ret;
   316	
   317	    ctx->current_chunk.crc = read_u32(ctx->data);
   318	
   319	    if(ctx->cur_actual_crc != ctx->current_chunk.crc)
   320	    {
   321	        if(is_critical_chunk(&ctx->current_chunk))
   322	        {
   323	            if(ctx->crc_action_critical == SPNG_CRC_USE) return 0;
   324	        }
   325	        else
   326	        {
   327	            if(ctx->crc_action_ancillary == SPNG_CRC_USE) return 0;
   328	            if(ctx->crc_action_ancillary == SPNG_CRC_DISCARD) return SPNG_CRC_DISCARD;
   329	        }
   330	
   331	        return SPNG_ECHUNK_CRC;
   332	    }
   333	  
   334	    return 0;
   335	}
