   429	/* Read at least one byte from the IDAT stream */
   430	static int read_idat_bytes(spng_ctx *ctx, uint32_t *bytes_read)
   431	{
   432	    if(ctx == NULL || bytes_read == NULL) return 1;
   433	    if(memcmp(ctx->current_chunk.type, type_idat, 4)) return SPNG_EIDAT_TOO_SHORT;
   434	
   435	    int ret;
   436	    uint32_t len;
   437	
   438	    while(!ctx->cur_chunk_bytes_left)
   439	    {
   440	        ret = read_header(ctx, NULL);
   441	        if(ret) return ret;
   442	
   443	        if(memcmp(ctx->current_chunk.type, type_idat, 4)) return SPNG_EIDAT_TOO_SHORT;
   444	    }
   445	
   446	    if(ctx->streaming)
   447	    {/* TODO: calculate bytes to read for progressive reads */
   448	        len = SPNG_READ_SIZE;
   449	        if(len > ctx->current_chunk.length) len = ctx->current_chunk.length;
   450	    }
   451	    else len = ctx->current_chunk.length;
   452	
   453	    ret = read_chunk_bytes(ctx, len);
   454	
   455	    *bytes_read = len;
   456	
   457	    return ret;
