   520	/* Defilter *scanline in-place.
   521	   *prev_scanline and *scanline should point to the first pixel,
   522	   scanline_width is the width of the scanline without the filter byte.
   523	   */
   524	static int defilter_scanline(const unsigned char *prev_scanline, unsigned char *scanline,
   525	                             size_t scanline_width, unsigned bytes_per_pixel, unsigned filter)
   526	{
   527	    if(prev_scanline == NULL || scanline == NULL || !scanline_width) return 1;
   528	
   529	    size_t i;
   530	
   531	    if(filter == 0) return 0;
   532	
   533	#ifndef SPNG_DISABLE_OPT
   534	    if(filter == SPNG_FILTER_TYPE_UP) goto no_opt;
   535	
   536	    if(bytes_per_pixel == 4)
   537	    {
   538	        if(filter == SPNG_FILTER_TYPE_SUB)
   539	            defilter_sub4(scanline_width, scanline);
   540	        else if(filter == SPNG_FILTER_TYPE_AVERAGE)
   541	            defilter_avg4(scanline_width, scanline, prev_scanline);
   542	        else if(filter == SPNG_FILTER_TYPE_PAETH)
   543	            defilter_paeth4(scanline_width, scanline, prev_scanline);
   544	        else return SPNG_EFILTER;
   545	
   546	        return 0;
   547	    }
   548	    else if(bytes_per_pixel == 3)
   549	    {
   550	        if(filter == SPNG_FILTER_TYPE_SUB)
   551	            defilter_sub3(scanline_width, scanline);
   552	        else if(filter == SPNG_FILTER_TYPE_AVERAGE)
   553	            defilter_avg3(scanline_width, scanline, prev_scanline);
   554	        else if(filter == SPNG_FILTER_TYPE_PAETH)
   555	            defilter_paeth3(scanline_width, scanline, prev_scanline);
   556	        else return SPNG_EFILTER;
   557	
   558	        return 0;
   559	    }
   560	no_opt:
   561	#endif
   562	
   563	    if(filter > 4) return SPNG_EFILTER;
   564	
   565	    for(i=0; i < scanline_width; i++)
   566	    {
   567	        uint8_t x, a, b, c;
   568	
   569	        if(i >= bytes_per_pixel)
   570	        {
   571	            memcpy(&a, scanline + i - bytes_per_pixel, 1);
   572	            memcpy(&b, prev_scanline + i, 1);
   573	            memcpy(&c, prev_scanline + i - bytes_per_pixel, 1);
   574	        }
   575	        else /* first pixel in row */
   576	        {
   577	            a = 0;
   578	            memcpy(&b, prev_scanline + i, 1);
   579	            c = 0;
   580	        }
   581	
   582	        memcpy(&x, scanline + i, 1);
   583	
   584	        switch(filter)
   585	        {
   586	            case SPNG_FILTER_TYPE_SUB:
   587	            {
   588	                x = x + a;
